begin;
do $test$
declare a uuid:=gen_random_uuid();b uuid:=gen_random_uuid();c uuid:=gen_random_uuid();invite text:=gen_random_uuid()::text||'@classpulse.invalid';ra jsonb;rb jsonb;rooma uuid;roomb uuid;doc jsonb;old_session jsonb;recent_session jsonb;quick jsonb;entry jsonb;feed jsonb;stats jsonb;f jsonb;denied boolean;student uuid;
 label text:='USAGE-'||upper(substr(md5(random()::text),1,10));
begin
 begin
 insert into private.faculty_approvals(email) values(a::text||'@classpulse.invalid'),(b::text||'@classpulse.invalid'),(c::text||'@classpulse.invalid'),(invite);
 insert into auth.users(id,email,email_confirmed_at,raw_user_meta_data,is_anonymous) values(a,a::text||'@classpulse.invalid',now(),'{"full_name":"Usage admin"}',false),(b,b::text||'@classpulse.invalid',now(),'{"full_name":"Usage faculty"}',false),(c,c::text||'@classpulse.invalid',null,'{"full_name":"Usage unconfirmed"}',false);
 insert into private.classpulse_admins(user_id) values(a);
 execute 'set local role authenticated';perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'is_anonymous',false)::text,true);
 ra:=public.classpulse_save_room(null,label||'-A');select id into rooma from public.rooms where roster_id=(ra->>'id')::uuid;
 perform public.classpulse_import_roster((ra->>'id')::uuid,'[{"id":"001","name":"Private Student One","emailid":"student-hidden@classpulse.invalid"}]');
 perform public.classpulse_launch_quick(rooma,'quick_mcq',3,'Admin activity','admin-usage-open');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',b,'is_anonymous',false)::text,true);
 rb:=public.classpulse_save_room(null,label||'-B');select id into roomb from public.rooms where roster_id=(rb->>'id')::uuid;
 perform public.classpulse_import_roster((rb->>'id')::uuid,'[{"id":"001","name":"Private Student One","emailid":"student-hidden@classpulse.invalid"}]');
 doc:=public.classpulse_save_quiz(null,null,'Usage fixture quiz','[{"type":"short_answer","prompt":"Private prompt not for admin","points":1,"options":[],"correct_position":null,"accepted_answers":["private-answer-marker"],"manual_grading":false}]',null,null);
 old_session:=public.classpulse_launch_quiz(roomb,(doc->>'quiz_id')::uuid,(doc->>'version_id')::uuid,(doc->>'revision')::integer);perform public.classpulse_start_session((old_session->>'id')::uuid);
 execute 'reset role';execute 'set local role anon';perform set_config('request.jwt.claims','{}',true);
 entry:=public.classpulse_student_join(label||'-B','001');feed:=public.classpulse_student_question((entry->>'token')::uuid);perform public.classpulse_submit_answer((entry->>'token')::uuid,(feed->'question'->>'id')::uuid,null,'private-answer-marker');
 execute 'reset role';execute 'set local role authenticated';perform set_config('request.jwt.claims',jsonb_build_object('sub',b,'is_anonymous',false)::text,true);perform public.classpulse_end_session((old_session->>'id')::uuid);
 execute 'reset role';
 update public.quiz_sessions set created_at=now()-interval '100 days',ended_at=now()-interval '100 days' where id=(old_session->>'id')::uuid;
 update public.session_participants set joined_at=now()-interval '100 days' where session_id=(old_session->>'id')::uuid;
 update public.quiz_responses set submitted_at=now()-interval '100 days' where session_id=(old_session->>'id')::uuid;
 execute 'set local role authenticated';
 doc:=public.classpulse_get_quiz((doc->>'quiz_id')::uuid);
 recent_session:=public.classpulse_launch_quiz(roomb,(doc->>'quiz_id')::uuid,(doc->>'version_id')::uuid,(doc->>'revision')::integer);perform public.classpulse_start_session((recent_session->>'id')::uuid);
 execute 'reset role';execute 'set local role anon';perform set_config('request.jwt.claims','{}',true);
 entry:=public.classpulse_student_join(label||'-B','001');feed:=public.classpulse_student_question((entry->>'token')::uuid);perform public.classpulse_submit_answer((entry->>'token')::uuid,(feed->'question'->>'id')::uuid,null,'private-answer-marker');
 execute 'reset role';execute 'set local role authenticated';perform set_config('request.jwt.claims',jsonb_build_object('sub',b,'is_anonymous',false)::text,true);perform public.classpulse_end_session((recent_session->>'id')::uuid);
 execute 'reset role';
 update public.quiz_sessions set created_at=now()-interval '10 days',ended_at=now()-interval '9 days' where id=(recent_session->>'id')::uuid;
 update public.session_participants set joined_at=now()-interval '10 days' where session_id=(recent_session->>'id')::uuid;
 update public.quiz_responses set submitted_at=now()-interval '10 days' where session_id=(recent_session->>'id')::uuid;
 select student_id into student from public.session_roster_students where session_id=(recent_session->>'id')::uuid;
 insert into private.report_email_jobs(teacher_id,session_id,student_id,recipient,fingerprint,status) values(b,(recent_session->>'id')::uuid,student,'student-hidden@classpulse.invalid','usage-fixture-fingerprint','accepted');
 execute 'set local role authenticated';
 quick:=public.classpulse_launch_quick(roomb,'quick_tf',2,'Quick fixture','admin-usage-quick');
 execute 'reset role';execute 'set local role anon';perform set_config('request.jwt.claims','{}',true);
 entry:=public.classpulse_student_join(label||'-B','001');feed:=public.classpulse_student_question((entry->>'token')::uuid);perform public.classpulse_submit_answer((entry->>'token')::uuid,(feed->'question'->>'id')::uuid,1,null);
 execute 'reset role';execute 'set local role authenticated';perform set_config('request.jwt.claims',jsonb_build_object('sub',b,'is_anonymous',false)::text,true);perform public.classpulse_end_session((quick->>'id')::uuid);
 denied:=false;begin perform public.classpulse_admin_usage(30);exception when raise_exception then denied:=true;end;if not denied then raise exception 'FAIL: ordinary faculty sees platform usage';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',b,'is_anonymous',false,'user_metadata',jsonb_build_object('role','admin'))::text,true);
 denied:=false;begin perform public.classpulse_admin_usage(30);exception when raise_exception then denied:=true;end;if not denied then raise exception 'FAIL: spoofed admin metadata';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'is_anonymous',false)::text,true);
 stats:=public.classpulse_admin_usage(30);
 select value into f from jsonb_array_elements(stats->'faculty') where value->>'id'=b::text;
 if f->>'active'<>'true' or (f->>'activities_launched')::int<>2 or (f->>'quizzes_conducted')::int<>1 or (f->>'quick_questions_conducted')::int<>1 or (f->>'student_participations')::int<>2 then raise exception 'FAIL: 30-day grouping or repeat participation';end if;
 if (stats->'accounts'->>'registered_faculty')::int<3 or (stats->'accounts'->>'confirmed_faculty')::int<2 or (stats->'accounts'->>'awaiting_confirmation')::int<1 or (stats->'accounts'->>'approved_not_registered')::int<1 then raise exception 'FAIL: account counts';end if;
 if (stats->'usage'->>'report_emails_accepted')::int<1 or (stats->'usage'->>'answers_saved')::int<2 or (stats->'usage'->>'current_sessions')::int<1 then raise exception 'FAIL: secondary counts';end if;
 if jsonb_array_length(stats->'monthly_trend')<>6 then raise exception 'FAIL: six month trend';end if;
 if stats::text like '%private-answer-marker%' or stats::text like '%Private Student One%' or stats::text like '%student-hidden@classpulse.invalid%' or stats::text like '%Private prompt not for admin%' then raise exception 'FAIL: student content leaked';end if;
 stats:=public.classpulse_admin_usage(7);select value into f from jsonb_array_elements(stats->'faculty') where value->>'id'=b::text;
 if (f->>'quizzes_conducted')::int<>0 or (f->>'quick_questions_conducted')::int<>1 or (f->>'activities_launched')::int<>1 or (f->>'student_participations')::int<>1 then raise exception 'FAIL: 7-day filtering';end if;
 stats:=public.classpulse_admin_usage(0);select value into f from jsonb_array_elements(stats->'faculty') where value->>'id'=b::text;
 if (f->>'quizzes_conducted')::int<>2 or (f->>'activities_launched')::int<>3 or (f->>'student_participations')::int<>3 then raise exception 'FAIL: all-time filtering';end if;
 stats:=public.classpulse_admin_usage(90);select value into f from jsonb_array_elements(stats->'faculty') where value->>'id'=b::text;if (f->>'quizzes_conducted')::int<>1 then raise exception 'FAIL: 90-day filtering';end if;
 denied:=false;begin perform public.classpulse_admin_usage(1);exception when raise_exception then denied:=true;end;if not denied then raise exception 'FAIL: invalid period';end if;
 denied:=false;begin perform public.classpulse_admin_usage(null);exception when raise_exception then denied:=true;end;if not denied then raise exception 'FAIL: null period';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',b,'is_anonymous',false)::text,true);
 perform public.classpulse_library_action('quiz',(doc->>'quiz_id')::uuid,'delete');
 perform public.classpulse_set_report_deleted(array[(recent_session->>'id')::uuid],true);
 perform public.classpulse_set_room_deleted((rb->>'id')::uuid,true);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'is_anonymous',false)::text,true);
 stats:=public.classpulse_admin_usage(30);select value into f from jsonb_array_elements(stats->'faculty') where value->>'id'=b::text;
 if (f->>'quizzes_conducted')::int<>1 or (f->>'quick_questions_conducted')::int<>1 or (f->>'student_participations')::int<>2 then raise exception 'FAIL: historical usage lost after deletion';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',c,'is_anonymous',false,'email_confirmed_at',now())::text,true);
 denied:=false;begin perform public.classpulse_admin_usage(30);exception when raise_exception then denied:=true;end;if not denied then raise exception 'FAIL: unconfirmed actor';end if;
 execute 'reset role';update private.faculty_approvals set enabled=false where email=a::text||'@classpulse.invalid';execute 'set local role authenticated';perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'is_anonymous',false)::text,true);
 denied:=false;begin perform public.classpulse_admin_usage(30);exception when raise_exception then denied:=true;end;if not denied then raise exception 'FAIL: revoked administrator';end if;
 execute 'reset role';execute 'set local role anon';perform set_config('request.jwt.claims','{}',true);
 denied:=false;begin perform public.classpulse_admin_usage(30);exception when insufficient_privilege then denied:=true;end;if not denied then raise exception 'FAIL: anonymous platform usage';end if;
 execute 'reset role';raise exception using errcode='CP001',message='Rollback fixtures';
 exception when sqlstate 'CP001' then null;
 end;
 if exists(select 1 from auth.users where id in(a,b,c)) then raise exception 'FAIL: fixtures remain';end if;
end $test$;
rollback;
select 'PASS: administrator usage statistics, period filters, historic counts and student privacy verified; fixtures rolled back' as result;
